begin;
-- One shared workflow for this CRM's authenticated team.
create table public.project_defaults (
    id boolean primary key default true check (id),
    steps jsonb not null default '[]'::jsonb check (jsonb_typeof(steps) = 'array'),
    revision integer not null default 1
);
alter table public.project_defaults enable row level security;
grant select, update on public.project_defaults to authenticated;
revoke all on public.project_defaults from anon;
create policy "Team can read project defaults" on public.project_defaults
    for select to authenticated using (true);
create policy "Team can edit project defaults" on public.project_defaults
    for update to authenticated using (true) with check (true);
insert into public.project_defaults (steps) values ('[{"id": "precon-step-1", "title": "REVIEW PROJECT INFORMATION", "tasks": [{"id": "precon-step-1-task-1", "title": "Review Project Details", "description": "Go over notes, plans, measurements, photos, and videos from the onsite consultation. Review the requested scope, existing conditions, client preferences, budget discussions, timeline expectations, and any other information already collected.", "template": ""}, {"id": "precon-step-1-task-2", "title": "Identify Questions & Information Needed", "description": "Identify anything that is unclear, missing, or needs to be confirmed before building the estimate. This can include scope details, material selections, measurements, site conditions, client expectations, or technical questions for production.", "template": ""}, {"id": "precon-step-1-task-3", "title": "Discuss Project Details with Internal Team", "description": "Talk with the sales team and other relevant team members to establish budget and timeline expectations, specific client requests, potential permit requirements, known site conditions, and any concerns that could affect the estimate.", "template": ""}]}, {"id": "precon-step-2", "title": "CONFIRM PROJECT DETAILS", "tasks": [{"id": "precon-step-2-task-1", "title": "Confirm Details with Client", "description": "Contact the client to clarify any questions about the scope, materials, design preferences, specific requests, budget, timeline, or information from the onsite consultation. Do not make assumptions when the client can provide clarification.", "template": ""}, {"id": "precon-step-2-task-2", "title": "Provide Project Info & Material Resources", "description": "Send the client relevant PQD portfolio photos or previous work, along with vendors, showrooms, and stores where they can review and select materials such as flooring, tile, cabinets, countertops, paint, fixtures, and other finishes. Collect or track selections as needed and determine whether items will be client-selected, PQD-provided, based on an allowance, or specified as a particular product.", "template": ""}, {"id": "precon-step-2-task-3", "title": "Confirm Final Scope & Expectations", "description": "Make sure the scope being estimated matches what the client actually wants, including any additions, exclusions, phasing, material selections, and specific expectations discussed after the onsite consultation.", "template": ""}]}, {"id": "precon-step-3", "title": "BUILD ESTIMATE", "tasks": [{"id": "precon-step-3-task-1", "title": "Build Estimate Scope", "description": "Develop the estimate using the information collected and the internal budget. Organize the work by trade or work area and include the necessary labor, materials, demolition, preparation, installation, disposal, finishing, and associated work required to complete the project.", "template": ""}, {"id": "precon-step-3-task-2", "title": "Add Pricing, Allowances & Notes", "description": "Apply pricing, material allowances, subcontractor costs, permits, equipment, disposal, contingency, overhead, and profit as appropriate. Add assumptions, exclusions, client-provided items, and change order disclaimers where needed.", "template": ""}, {"id": "precon-step-3-task-3", "title": "Prepare Client-Facing Estimate", "description": "Format the estimate so it is clear, professional, and easy for the client to understand. Make sure the scope, pricing, selections, allowances, and notes accurately reflect the conversations and decisions made during pre-construction.", "template": ""}]}, {"id": "precon-step-4", "title": "VERIFY ESTIMATE INTERNALLY", "tasks": [{"id": "precon-step-4-task-1", "title": "Review Technical Scope with Production", "description": "Review the estimate with the PM or production team to confirm construction methods, disclaimers, permit & code considerations, labor & material requirements, and any technical questions. Consolidate questions into a short internal review rather than handling them one at a time.", "template": ""}, {"id": "precon-step-4-task-2", "title": "Verify Internal Budget & Payment Schedule", "description": "Confirm that labor, materials, subcontractors, permits, equipment, disposal, allowances, contingency, overhead, and profit are realistic for the project and that the estimate is financially viable. Determine and outline client payment schedule.", "template": ""}, {"id": "precon-step-4-task-3", "title": "Final Estimate Review", "description": "Review the completed estimate and confirm that the scope, pricing, client expectations, budget, and project approach are aligned. Input necessary notes, disclaimers, and ‘client to purchase’ lists.", "template": ""}]}, {"id": "precon-step-5", "title": "SEND ESTIMATE & FOLLOW UP", "tasks": [{"id": "precon-step-5-task-1", "title": "Send Initial Estimate", "description": "Send the finalized estimate to the client through the approved company platform or email. Confirm the estimate has been internally reviewed, the scope is accurate, and the estimate is ready to be presented to the client.", "template": "Subject: Project Proposal\n\nHello [[FirstName]],\n\nHope you’re doing well! Val and I have gone over all the details and finalized your proposal for the discussed scope of work. Please take a moment to look that over and don’t hesitate to reach out if there is anything you’d like to discuss. We''re happy to walk through the proposal with you if that''s at all helpful.\n\nLook forward to hearing from you!\n\nAlex & PQD Remodels Team"}, {"id": "precon-step-5-task-2", "title": "Estimate Follow-Up #1", "description": "Send 2-3 business days after the initial estimate. Record the follow-up in the CRM and adjust the message as needed based on any previous communication with the client.", "template": "Subject: Proposal Follow-Up\n\nHello [[FirstName]],\n\nJust checking in to see if you had a chance to review the estimate we sent over. Don''t hesitate to reach out if you have any questions, need clarification, or would like to make any adjustments. Phone, text, or email, whichever works best for you.\n\nWe’re excited about the possibility of working together and would love to get your project on our schedule.\n\nLook forward to hearing from you!\n\nAlex & PQD Remodels Team"}, {"id": "precon-step-5-task-3", "title": "Estimate Follow-Up #2", "description": "Send 4-5 business days after Follow-Up #1 if the client has not responded. Record the follow-up in the CRM and address any questions or concerns if the client responds.", "template": "Subject: Checking In On Your Proposal\n\nHello [[FirstName]],\n\nIt''s been a few days since we''ve sent over your estimate, and we haven''t seen a response come through. Did we miss a message from you somewhere?\n\nWe''re here if you have any questions or concerns!\n\nAlex & PQD Remodels Team"}, {"id": "precon-step-5-task-4", "title": "Estimate Follow-Up #3", "description": "Send 5-7 business days after Follow-Up #2 if the client has not responded. This is the final standard follow-up before considering the project on hold or waiting for the client to reconnect.", "template": "Subject: Final Proposal Follow-Up\n\nHello [[FirstName]],\n\nI just wanted to follow up one last time regarding your estimate. We haven’t heard back, so I wanted to check if you’re still interested in moving forward.\n\nIf the timing isn’t right, no problem at all. We’d be happy to reconnect whenever it makes sense for you.\n\nThanks again for the opportunity, and feel free to reach out anytime.\n\nAlex & PQD Remodels Team"}, {"id": "precon-step-5-task-5", "title": "Address Client Questions", "description": "Respond to questions or concerns about the estimate, scope, pricing, materials, allowances, or project expectations. If the client requests changes to the scope, materials, pricing, allowances, options, phasing, or specific line items, continue to the next step.", "template": ""}]}, {"id": "precon-step-6", "title": "REVISE ESTIMATE", "tasks": [{"id": "precon-step-6-task-1", "title": "Document Requested Changes", "description": "Record all requested changes to scope, materials, pricing, allowances, options, or project phasing. Clearly identify what is being added, removed, or changed before revising the estimate.", "template": ""}, {"id": "precon-step-6-task-2", "title": "Update & Review Estimate", "description": "Revise the estimate and update pricing based on the requested changes. Verify that the revised scope remains accurate and profitable and review with Sales or Production when needed. Note change in cost for every adjusted details", "template": ""}, {"id": "precon-step-6-task-3", "title": "Send Updated Estimate", "description": "Once revisions are complete, send the updated estimate to the client. Confirm that the revised proposal reflects the details discussed and ask the client to review the changes.", "template": "Subject: Updated Proposal\n\nHello [[FirstName]],\n\nI''ve gone through and adjusted your proposal to reflect the details that were discussed. Let me know if everything looks correct, or if there''s anything else you''d like to go over.\n\nLook forward to hearing from you!\n\nAlex"}, {"id": "precon-step-6-task-4", "title": "Updated Estimate Follow-Up #1", "description": "Send 2-3 business days after the updated estimate is sent if the client has not responded. Record the follow-up in the CRM and address any questions or additional requested changes.", "template": "Subject: Updated Estimate Follow-Up\n\nHello [[FirstName]],\n\nJust wanted to check in and see if you had a chance to review the updated estimate. Please let me know if everything looks good on your end, or if there’s anything else you’d like to adjust. I’m happy to go over any details with you as well.\n\nLook forward to hearing your thoughts.\n\nAlex"}, {"id": "precon-step-6-task-5", "title": "Updated Estimate Follow-Up #2", "description": "Send 4-5 business days after Updated Estimate Follow-Up #1 if the client has not responded. If everything is approved, the project can move toward the agreement. If the client has additional changes or questions, address them before proceeding.", "template": "Subject: Checking In On Updated Estimate\n\nHello [[FirstName]],\n\nI wanted to follow up on the updated estimate and see where things stand on your end.\n\nIf everything looks good, we can move forward with the agreement and get things lined up. If there’s anything you’d still like to adjust or go over, I’m happy to help. Just let me know what you’re thinking.\n\nAlex & Pro Quality Designs Team"}, {"id": "precon-step-6-task-6", "title": "Updated Estimate Follow-Up #3", "description": "Send 5-7 business days after Updated Estimate Follow-Up #2 if the client has not responded. This is the final standard follow-up for the revised estimate. If there is still no response, consider the project on hold until the client reconnects.", "template": "Subject: Final Updated Estimate Follow-Up\n\nHello [[FirstName]],\n\nI wanted to reach out one last time regarding your updated estimate.\n\nWe haven’t heard back, so I’ll assume things are on hold for now. If that changes and you’d like to revisit the project, feel free to reach out anytime.\n\nAppreciate the opportunity to take a look at this with you.\n\nAlex & Pro Quality Designs Team"}]}, {"id": "precon-step-7", "title": "CLIENT APPROVAL & CONTRACT APPROVAL", "tasks": [{"id": "precon-step-7-task-1", "title": "Confirm Client Approval", "description": "Receive written confirmation that the client wants to move forward with the approved estimate. Confirm any remaining selections or clarifications and make sure there are no unresolved scope or pricing questions before creating the contract. Record the client''s approval in the CRM.", "template": ""}, {"id": "precon-step-7-task-2", "title": "Select Contract & Create Project Agreement", "description": "Select the appropriate contract based on project size, complexity, duration, payment structure, and other applicable factors. For projects under $10,000, use the General Service Agreement in Joist. For larger projects, use the appropriate Small Job or Large Job contract template from the company Google Drive. Create a project-specific copy, name it using the required client naming format, and move it into the Client Agreements folder. If uncertain which contract to use, consult a direct superior.", "template": ""}, {"id": "precon-step-7-task-3", "title": "Complete Construction Agreement & Exhibits", "description": "Complete all required contractor, property, pricing, payment, and signature information. Verify property information through County or City GIS when necessary. Enter the anticipated completion date when reasonably accurate, or leave it blank if one cannot yet be determined. Enter the exact approved contract price, including applicable taxes and fees, and complete the appropriate payment schedule. Do not modify the final payment provisions in the template. Copy the approved estimate into Exhibit B, including the full scope of work, Client to Order list, client-provided materials, specified products/materials, and project-specific clarifications. For Oregon projects, complete Exhibit E with the required property owner, mailing address, scope, ordering party, and jobsite information.", "template": ""}, {"id": "precon-step-7-task-4", "title": "Review Contract & Prepare DocuSign", "description": "Complete a full contract review before uploading to DocuSign. Verify the correct template, client information, property information, contract value, payment schedule, Exhibit B, Exhibit E when required, formatting, and all required fields. Upload the contract and exhibits to DocuSign and insert all required contractor signature fields. For Oregon contracts, complete the required Exhibit D fields, including CCB #238128 and the applicable company signature and date fields. Insert all required client information, initials, signatures, and state-specific Exhibit D fields, making sure every field is assigned to the correct signer.", "template": ""}, {"id": "precon-step-7-task-5", "title": "Final Review & Send Contract", "description": "Perform the final DocuSign review before sending. Verify all contractor and client fields are present and assigned correctly, client names and email addresses are accurate, all exhibits and attachments are included, attached files are named correctly, the contract value matches the approved estimate, and no information is missing. Send the DocuSign envelope to the client and ensure all required company signature fields are completed by the authorized company signer. Monitor the envelope until all required client and company signatures are completed. The contract is not considered fully executed until all required signatures are complete.", "template": ""}, {"id": "precon-step-7-task-6", "title": "Save Executed Contract", "description": "Once all required signatures have been obtained, download the completed DocuSign agreement as a single PDF including all attached documents. Verify that all signatures and attachments are included, rename the completed document using the existing agreement naming format, and replace the existing agreement file in the Client Agreements folder.", "template": ""}]}, {"id": "precon-step-8", "title": "CONTRACT EXECUTION & DEPOSIT", "tasks": [{"id": "precon-step-8-task-1", "title": "Request Contract Signature & Deposit", "description": "After the contract has been sent, follow up with the client regarding the required signed contract and deposit payment. Provide payment instructions and confirm the client understands that both the signed contract and deposit are required before the project can move into scheduling and production preparation.", "template": "Hello [[FirstName]],\n\nWe’re glad to hear you’ve chosen to move forward with us on your project! Before we proceed, there are a couple of items we need to complete, including a signed contract and the deposit payment.\n\nIf you have not already done so, please review the contract we''ve sent over and sign it to acknowledge acceptance of all terms and conditions. Once the contract is signed, we’ll need to collect the deposit. Payment can be made using the following methods:\n\nCash or Check can be arranged for pick-up, or sent/made payable to:\nPro Quality Designs\n12209 NE Fourth Plain BLVD\nSuite K\nVancouver, WA 98682\n\nVenmo & Zelle:\nproqualitydesignsllc@gmail.com\n\nCredit or debit card payments are also accepted, but are subject to a 3.7% processing fee plus a $0.49 transaction charge.\n\nPlease let us know which payment method works best for you. Once payment is processed, we’ll get your project scheduled and begin ordering the necessary materials. In the meantime, I’ll meet with our production team to get them familiarized with your project.\n\nThank you,\nAlex"}, {"id": "precon-step-8-task-2", "title": "Monitor & Confirm Contract Execution", "description": "Monitor the contract until all required client and company signatures are completed. Confirm that all required client signatures, initials, and company signatures have been completed and that the agreement is fully executed. If signatures remain outstanding, follow up with the appropriate party and document the communication.", "template": ""}, {"id": "precon-step-8-task-3", "title": "Request & Process Deposit", "description": "Send the deposit request, receive payment through an approved payment method, account for applicable payment processing fees, and confirm that the required deposit has been received and cleared. Save payment confirmation to the project records and update the CRM/project management system. The project should not move into scheduling or production preparation until the deposit has been received and confirmed.", "template": ""}, {"id": "precon-step-8-task-4", "title": "Complete Project Documentation", "description": "Confirm all required project records are complete and up to date before advancing the project. Verify that the final estimate and revision history, executed contract, deposit/payment confirmation, client communication records, scope revision notes, material selection records, and CRM/project management records are documented and organized.", "template": ""}, {"id": "precon-step-8-task-5", "title": "Release Project to Production", "description": "Once the signed contract and cleared deposit are confirmed, update the CRM, notify the production team, notify the client as appropriate, and release the project for scheduling and material procurement. Confirm the production team has the finalized project information needed to begin the next phase.", "template": ""}]}]'::jsonb);
alter table public.clients add column project_steps jsonb
    check (project_steps is null or jsonb_typeof(project_steps) = 'array');
-- Snapshot defaults atomically with creation, including inserts outside the web UI.
create function public.assign_default_project_steps() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
    select steps into new.project_steps from public.project_defaults where id = true;
    new.project_steps := coalesce(new.project_steps, '[]'::jsonb);
    return new;
end;
$$;
revoke all on function public.assign_default_project_steps() from public;
create trigger assign_default_project_steps before insert on public.clients
    for each row execute function public.assign_default_project_steps();
commit;
